package com.clara.workspace.runtime;
import com.clara.kernel.exception.ClaraException;
import com.clara.kernel.exception.ErrorCodes;
import com.clara.workspace.api.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;import org.junit.*;import org.junit.rules.TemporaryFolder;import static org.junit.Assert.*;
public class FileSystemWorkspaceReaderTest {@Rule public final TemporaryFolder folder=new TemporaryFolder();private Path root;private WorkspacePolicy policy;private FileSystemWorkspaceReader reader;private WorkspaceRef workspace;
 @Before public void setUp()throws Exception{root=folder.newFolder("workspace").toPath();policy=new WorkspacePolicy(new HashSet<String>(Arrays.asList(".txt",".java",".pdf",".docx",".xlsx")),Collections.singleton("ignored"),Collections.singleton("credentials.txt"),10,100,200,false);reader=new FileSystemWorkspaceReader(policy);workspace=new WorkspaceRef("w","tenant","run",root.toAbsolutePath(),WorkspaceAccessMode.PREVIEW_WRITE);}
 @Test public void scansAllowedFilesAndExcludesInternalAndSensitiveFiles()throws Exception{Files.write(root.resolve("a.txt"),"hello".getBytes(StandardCharsets.UTF_8));Files.write(root.resolve(".env"),"secret".getBytes(StandardCharsets.UTF_8));Files.createDirectories(root.resolve(".clara"));Files.write(root.resolve(".clara/state.txt"),"state".getBytes(StandardCharsets.UTF_8));Files.write(root.resolve("credentials.txt"),"secret".getBytes(StandardCharsets.UTF_8));Files.write(root.resolve("image.png"),new byte[]{1});
  WorkspaceSnapshot snapshot=reader.scan(workspace,policy);assertEquals(1,snapshot.getFiles().size());assertEquals("a.txt",snapshot.getFiles().get(0).getRelativePath());assertEquals(64,snapshot.getFingerprint().length());assertEquals("hello",new String(reader.read(workspace,"a.txt").getContent(),StandardCharsets.UTF_8));}
 @Test public void rejectsTraversalInternalPathsAndOversizedRead()throws Exception{Files.write(root.resolve("large.txt"),new byte[101]);Files.createDirectories(root.resolve(".clara"));Files.write(root.resolve(".clara/state.txt"),new byte[]{1});assertCode(ErrorCodes.WORKSPACE_ACCESS_DENIED,new Runnable(){public void run(){reader.read(workspace,"../outside.txt");}});assertCode(ErrorCodes.WORKSPACE_ACCESS_DENIED,new Runnable(){public void run(){reader.read(workspace,".clara/state.txt");}});assertCode(ErrorCodes.WORKSPACE_RESOURCE_LIMIT,new Runnable(){public void run(){reader.read(workspace,"large.txt");}});}
 @Test public void reportsTruncatedSnapshotAtLimits()throws Exception{Files.write(root.resolve("a.txt"),new byte[80]);Files.write(root.resolve("b.txt"),new byte[80]);Files.write(root.resolve("c.txt"),new byte[80]);WorkspaceSnapshot snapshot=reader.scan(workspace,policy);assertTrue(snapshot.isTruncated());assertEquals(2,snapshot.getFiles().size());}
 private static void assertCode(String code,Runnable action){try{action.run();fail("expected "+code);}catch(
         ClaraException e){assertEquals(code,e.getError().getCode());}}
}
